import React, { useEffect, useRef } from 'react';
import p5 from 'p5';

const Background = () => {
    const sketchRef = useRef();

    useEffect(() => {
        const sketch = (p) => {
            let charSize = 35;
            let fallRate = charSize / 2;
            let streams = [];

            class Char {
                constructor(value, x, y, speed) {
                    this.value = value;
                    this.x = x;
                    this.y = y;
                    this.speed = speed;
                }

                draw() {
                    let distance = p.dist(p.mouseX, p.mouseY, this.x, this.y);
                    let opacity = p.map(distance, 0, 200, 255, 0);
                    opacity = p.constrain(opacity, 0, 255);
                    p.fill(120, 100, 100, opacity);
                    p.text(this.value, this.x, this.y);
                    this.y = this.y > p.height ? 0 : this.y + this.speed;
                }
            }

            class Stream {
                constructor(text, x) {
                    const y = p.random(-500, -50);
                    const speed = p.random(1, 5);
                    this.chars = [];
                    for (let i = 0; i < text.length; i++) {
                        this.chars.push(new Char(text[i], x, y + i * charSize, speed));
                    }
                }

                draw() {
                    p.fill(120, 100, 100);
                    this.chars.forEach((c, i) => {
                        const lit = p.random(100);
                        if (lit < 30) {
                            p.fill(120, 100, 90);
                        }
                        c.draw();
                    });
                }
            }

            const createStreams = () => {
                streams = [];
                for (let i = 0; i < p.width; i += charSize * 0.65) {
                    streams.push(new Stream(p.random(langs), i));
                }
            };

            p.setup = () => {
                p.createCanvas(p.windowWidth, p.windowHeight);
                createStreams();
                p.frameRate(60);
                p.colorMode(p.HSB);
                p.noStroke();
                p.textSize(charSize);
                p.textFont("monospace");
                p.background(0);
            };

            p.draw = () => {
                p.background(0, 0.4);
                streams.forEach((s) => s.draw());
            };

            p.windowResized = () => {
                p.resizeCanvas(p.windowWidth, p.windowHeight);
                p.background(0);
                createStreams();
            };

            // Add the windowResized listener
            p.windowResized = windowResized;
        };

        let myp5 = new p5(sketch, sketchRef.current);

        // Return a cleanup function to remove the sketch on unmount
        return () => {
            myp5.remove();
        };
    }, []);

    // Use a ref to reference the div that will contain the p5 sketch
    return <div ref={sketchRef} />;
};

export default Background;
